82	Status Hixl::HixlImpl::Initialize(const std::map<AscendString, AscendString> &options) {
83	  std::lock_guard<std::mutex> lk(mutex_);
84	  if (engine_ != nullptr) {
85	    HIXL_CHK_BOOL_RET_SPECIAL_STATUS(engine_->IsInitialized(), SUCCESS, "Already initialized");
86	  }
87	  HixlOptions parsed_options;
88	  engine_ = hixl::EngineFactory::CreateEngine(local_engine_, options, parsed_options);
89	  HIXL_CHECK_NOTNULL(engine_, "[HixlEngine] Created engine is null, please check your parameters! local_engine:%s",
90	                     local_engine_.c_str());
91	  HIXL_CHK_STATUS_RET(engine_->Initialize(parsed_options), "Failed to initialize Hixl.");
92	  Status ret = connect_pool_executor_.Initialize(parsed_options);
93	  if (ret != SUCCESS) {
94	    engine_->Finalize();
95	    engine_.reset();
96	    HIXL_LOGE(ret, "Failed to initialize ConnectPoolExecutor.");
97	    return ret;
98	  }
99	  return SUCCESS;
100	}
101	
102	void Hixl::HixlImpl::Finalize() {
103	  if (engine_ == nullptr) {
104	    HIXL_LOGE(FAILED, "engine is nullptr, check engine init");
105	    return;
106	  }
107	  connect_pool_executor_.Shutdown();
108	  engine_->Finalize();
109	  engine_.reset();
110	}
