200	Status Hixl::HixlImpl::GetTransferStatus(const TransferReq &req, TransferStatus &status) {
201	  HIXL_CHK_BOOL_RET_STATUS(engine_ != nullptr, FAILED, "engine is nullptr, check engine init");
202	  TransferStatus transfer_status = TransferStatus::WAITING;
203	  auto ret = engine_->GetTransferStatus(req, transfer_status);
204	  if (ret != SUCCESS) {
205	    status = TransferStatus::FAILED;
206	    HIXL_LOGE(ret, "Failed to get transfer status.");
207	    return ret;
208	  }
209	  status = transfer_status;
210	  return SUCCESS;
211	}
