241	Status Hixl::Initialize(const AscendString &local_engine, const std::map<AscendString, AscendString> &options) {
242	  HIXL_LOGI("Hixl initialize start");
243	  auto impl = llm::MakeUnique<HixlImpl>(local_engine);
244	  HIXL_CHK_BOOL_RET_STATUS(impl != nullptr, FAILED, "impl is nullptr, check Hixl construct");
245	  HIXL_CHK_STATUS_RET(impl->Initialize(options), "Failed to initialize Hixl");
246	  impl_ = std::move(impl);
247	  HIXL_LOGI("Hixl initialized successfully");
248	  return SUCCESS;
249	}
