251	void Hixl::Finalize() {
252	  HIXL_LOGI("Hixl finalize start");
253	  if (impl_ != nullptr) {
254	    impl_->Finalize();
255	    impl_.reset();
256	  }
257	  HIXL_LOGI("Hixl finalized successfully");
258	}
