260	Status Hixl::RegisterMem(const MemDesc &mem, MemType type, MemHandle &mem_handle) {
261	  HIXL_LOGI("RegisterMem start, type:%d, addr:%p, size:%zu", static_cast<int32_t>(type),
262	            reinterpret_cast<void *>(mem.addr), mem.len);
263	  HIXL_CHK_BOOL_RET_STATUS(impl_ != nullptr, FAILED, "impl is nullptr, check Hixl init");
264	  HIXL_CHK_STATUS_RET(impl_->RegisterMem(mem, type, mem_handle),
265	                      "Failed to register mem, "
266	                      "type:%d, addr:%p, size:%zu",
267	                      static_cast<int32_t>(type), reinterpret_cast<void *>(mem.addr), mem.len);
268	  HIXL_LOGI("RegisterMem success, type:%d, addr:%p, size:%zu, handle:%p", static_cast<int32_t>(type),
269	            reinterpret_cast<void *>(mem.addr), mem.len, mem_handle);
270	  return SUCCESS;
271	}
