273	Status Hixl::DeregisterMem(MemHandle mem_handle) {
274	  HIXL_LOGI("DeregisterMem start, mem_handle:%p", mem_handle);
275	  HIXL_CHK_BOOL_RET_STATUS(impl_ != nullptr, FAILED, "impl is nullptr, check Hixl init");
276	  HIXL_CHK_STATUS_RET(impl_->DeregisterMem(mem_handle), "Failed to deregister mem, mem_handle:%p", mem_handle);
277	  HIXL_LOGI("DeregisterMem success, mem_handle:%p", mem_handle);
278	  return SUCCESS;
279	}
