42	Status HixlEngine::InitServer(std::optional<uint32_t> listen_port, std::optional<uint32_t> max_active_channels) {
43	  std::string ip;
44	  int32_t port = 0;
45	  HIXL_CHK_STATUS_RET(ParseListenInfo(local_engine_, ip, port),
46	                      "[HixlEngine] Failed to parse ip and port, local_engine should be in form as below: "
47	                      "ipv4 should be 'host_ip:host_port' or 'host_ip' "
48	                      "ipv6 should be '[host_ip]:host_port' or '[host_ip]' "
49	                      "current local_engine:%s",
50	                      local_engine_.c_str());
51	  HIXL_CHK_STATUS_RET(server_.Initialize(ip, port, endpoint_list_, listen_port, max_active_channels),
52	                      "[HixlEngine] Failed to initialize HixlEngine, local_engine:%s", local_engine_.c_str());
53	  return SUCCESS;
