56	Status HixlEngine::Initialize(const HixlOptions &options) {
57	  HIXL_EVENT("[HixlEngine] initialize start, local_engine:%s", local_engine_.c_str());
58	  std::lock_guard<std::mutex> lock(mutex_);
59	  HIXL_CHK_STATUS_RET(options.CheckSupportedOptions(kSupportedOptions), "[HixlEngine] Unsupported option");
60	  const auto &raw = options.RawOptions();
61	  const auto &hixl_bp_it = raw.find(hixl::OPTION_BUFFER_POOL);
62	  const auto &adxl_bp_it = raw.find(adxl::OPTION_BUFFER_POOL);
63	  auto bp_it = (hixl_bp_it != raw.cend()) ? hixl_bp_it : adxl_bp_it;
64	  if (bp_it != raw.cend()) {
65	    HIXL_CHK_BOOL_RET_STATUS(std::string(bp_it->second.GetString()) == "0:0", PARAM_INVALID,
66	                             "Invalid option fields, OPTION_BUFFER_POOL for hixl engine only supports 0:0");
67	  }
68	  std::string local_comm_res;
69	  HIXL_CHK_STATUS_RET(EndpointGenerator::BuildEndpointList(options, local_engine_, local_comm_res, endpoint_list_),
70	                      "[HixlEngine] Failed to build endpoint list from options");
71	  auto global_resource_config = options.GlobalResourceCfg();
72	  std::optional<uint32_t> listen_port;
73	  if (global_resource_config.has_value()) {
74	    listen_port = global_resource_config->comm_resource_config.listen_port;
75	    qos_ = global_resource_config->comm_resource_config.qos;
76	    max_active_channels_ = global_resource_config->comm_resource_config.max_active_channels;
77	  } else {
78	    listen_port.reset();
79	    qos_.reset();
80	    max_active_channels_.reset();
81	  }
82	  HIXL_CHK_STATUS_RET(aclrt_context_.CreateContext(), "[HixlEngine] Failed to create optional aclrt context");
83	  HIXL_DISMISSABLE_GUARD(ctx_fail_guard, ([this]() { aclrt_context_.DestroyContext(); }));
84	  {
85	    auto with_context = aclrt_context_.GetContextGuard();
86	    HIXL_CHK_STATUS_RET(InitServer(listen_port, max_active_channels_),
87	                        "[HixlEngine] Failed to initialize server, local_engine:%s, local_comm_res:%s",
88	                        local_engine_.c_str(), local_comm_res.c_str());
89	  }
90	  rdma_traffic_class_ = options.RdmaTrafficClass().value_or(kRdmaTrafficClass);
91	  rdma_service_level_ = options.RdmaServiceLevel().value_or(kRdmaServiceLevel);
92	  auto_connect_ = options.AutoConnect().value_or(false);
93	  HIXL_CHK_STATUS_RET(client_manager_.Initialize(auto_connect_), "[HixlEngine] Failed to initialize client manager");
94	  HIXL_DISMISS_GUARD(ctx_fail_guard);
95	  is_initialized_ = true;
96	  HIXL_EVENT("[HixlEngine] initialize success, local_engine:%s, endpoint_count:%zu, auto_connect:%d",
97	             local_engine_.c_str(), endpoint_list_.size(), static_cast<int32_t>(auto_connect_.load()));
98	  return SUCCESS;
99	}
