101	Status HixlEngine::RegisterMem(const MemDesc &mem, MemType type, MemHandle &mem_handle) {
102	  HIXL_CHK_STATUS_RET(CheckInitialized(), "[HixlEngine] Failed to register mem, engine is not initialized");
103	  HIXL_EVENT("[HixlEngine] register mem start, local_engine:%s, type:%s, addr:%p, len:%zu", local_engine_.c_str(),
104	             MemTypeToString(type).c_str(), reinterpret_cast<void *>(mem.addr), mem.len);
105	  auto with_context = aclrt_context_.GetContextGuard();
106	  std::lock_guard<std::mutex> lock(mutex_);
107	  HIXL_CHK_STATUS_RET(server_.RegisterMem(mem, type, mem_handle),
108	                      "[HixlEngine] Failed to register mem, type:%s, addr:%p, size:%lu", MemTypeToString(type).c_str(),
109	                      reinterpret_cast<void *>(mem.addr), mem.len);
110	  MemHandleInfo mem_info = {mem_handle, mem, type};
111	  mem_map_.emplace(mem_handle, mem_info);
112	  HIXL_EVENT("[HixlEngine] register mem success, local_engine:%s, type:%s, addr:%p, len:%zu, handle:%p",
113	             local_engine_.c_str(), MemTypeToString(type).c_str(), reinterpret_cast<void *>(mem.addr), mem.len,
114	             mem_handle);
115	  return SUCCESS;
116	}
