118	Status HixlEngine::DeregisterMem(MemHandle mem_handle) {
119	  HIXL_EVENT("[HixlEngine] deregister mem start, local_engine:%s, handle:%p", local_engine_.c_str(), mem_handle);
120	  auto with_context = aclrt_context_.GetContextGuard();
121	  std::lock_guard<std::mutex> lock(mutex_);
122	  const auto &it = mem_map_.find(mem_handle);
123	  if (it == mem_map_.end()) {
124	    HIXL_LOGW("[HixlEngine] handle:%p is not registered", mem_handle);
125	    return SUCCESS;
126	  }
127	  HIXL_CHK_BOOL_RET_STATUS(
128	      client_manager_.IsEmpty(), FAILED,
129	      "[HixlEngine] Failed to deregister mem. All clients must be disconnected before deregistration, "
130	      "mem_handle: %p, local_engine: %s",
131	      mem_handle, local_engine_.c_str());
132	  const MemHandleInfo mem_info = it->second;
133	  HIXL_CHK_STATUS_RET(server_.DeregisterMem(mem_handle),
134	                      "[HixlEngine] Failed to deregister mem, mem_handle: %p, local_engine: %s", mem_handle,
135	                      local_engine_.c_str());
136	  mem_map_.erase(it);
137	  HIXL_EVENT("[HixlEngine] deregister mem success, local_engine:%s, type:%s, addr:%p, len:%zu, handle:%p",
138	             local_engine_.c_str(), MemTypeToString(mem_info.type).c_str(), reinterpret_cast<void *>(mem_info.mem.addr),
139	             mem_info.mem.len, mem_handle);
140	  return SUCCESS;
141	}
