143	Status HixlEngine::Connect(const AscendString &remote_engine, int32_t timeout_in_millis) {
144	  HIXL_CHK_STATUS_RET(CheckInitialized(), "[HixlEngine] Failed to connect, engine is not initialized");
145	  HIXL_CHK_BOOL_RET_STATUS(strcmp(local_engine_.c_str(), remote_engine.GetString()) != 0, PARAM_INVALID,
146	                           "[HixlEngine] Do not support connection with self, please check remote engine. "
147	                           "local_engine:%s, remote_engine:%s",
148	                           local_engine_.c_str(), remote_engine.GetString());
149	  HIXL_EVENT("[HixlEngine] connect start, local_engine:%s, remote_engine:%s, timeout_ms:%d", local_engine_.c_str(),
150	             remote_engine.GetString(), timeout_in_millis);
151	  auto with_context = aclrt_context_.GetContextGuard();
152	  ClientConfig config{};
153	  std::vector<MemHandleInfo> mem_info_list;
154	  BuildClientConfig(remote_engine, config, mem_info_list, timeout_in_millis);
155	  config.is_lazy = false;
156	  ClientPtr client_ptr = nullptr;
157	  Status ret = client_manager_.GetOrCreateClient(config, mem_info_list, timeout_in_millis, client_ptr);
158	  HIXL_CHK_BOOL_RET_SPECIAL_STATUS(ret == ALREADY_CONNECTED, ALREADY_CONNECTED,
159	                                   "[HixlEngine] remote_engine:%s is already connected to local_engine:%s",
160	                                   remote_engine.GetString(), local_engine_.c_str());
161	  HIXL_CHK_STATUS_RET(ret, "[HixlEngine] Failed to connect client, local_engine:%s, remote_engine:%s, timeout:%d ms",
162	                      local_engine_.c_str(), remote_engine.GetString(), timeout_in_millis);
163	  HIXL_EVENT("[HixlEngine] connect success, local_engine:%s, remote_engine:%s, timeout_ms:%d", local_engine_.c_str(),
164	             remote_engine.GetString(), timeout_in_millis);
165	  return SUCCESS;
166	}
