191	Status HixlEngine::TransferSync(const AscendString &remote_engine, TransferOp operation,
192	                                const std::vector<TransferOpDesc> &op_descs, int32_t timeout_in_millis) {
193	  HIXL_LOGI("[HixlEngine] Synchronous transmission started, local_engine:%s, remote_engine:%s, timeout:%d ms",
194	            local_engine_.c_str(), remote_engine.GetString(), timeout_in_millis);
195	  auto with_context = aclrt_context_.GetContextGuard();
196	  ClientPtr client_ptr;
197	  HIXL_CHK_STATUS_RET(AutoConnect(remote_engine, timeout_in_millis, client_ptr),
198	                      "[HixlEngine] Failed to auto connect before TransferSync, local_engine:%s, remote_engine:%s",
199	                      local_engine_.c_str(), remote_engine.GetString());
200	  HixlProfType type = (operation == READ ? HixlProfType::HixlOpBatchRead : HixlProfType::HixlOpBatchWrite);
201	  HIXL_API_PROFILING(type);
202	  Status ret = client_ptr->TransferSync(op_descs, operation, timeout_in_millis);
203	  if (ret != SUCCESS) {
204	    HIXL_LOGE(ret, "[HixlEngine] Failed to TransferSync, local_engine:%s, remote_engine:%s, timeout:%d ms",
205	              local_engine_.c_str(), remote_engine.GetString(), timeout_in_millis);
206	    HIXL_CHK_STATUS_RET(AutoDisconnect(remote_engine.GetString(), timeout_in_millis),
207	                        "[HixlEngine] Failed to disconnect on error.");
208	    return ret;
209	  }
210	  HIXL_LOGI("[HixlEngine] Synchronous transmission succeeded, local_engine:%s, remote_engine:%s, timeout:%d ms",
211	            local_engine_.c_str(), remote_engine.GetString(), timeout_in_millis);
212	  return SUCCESS;
213	}
