215	Status HixlEngine::TransferAsync(const AscendString &remote_engine, TransferOp operation,
216	                                 const std::vector<TransferOpDesc> &op_descs, const TransferArgs &optional_args,
217	                                 TransferReq &req) {
218	  HIXL_LOGI("[HixlEngine] Asynchronous transmission started, local_engine:%s, remote_engine:%s", local_engine_.c_str(),
219	            remote_engine.GetString());
220	  auto with_context = aclrt_context_.GetContextGuard();
221	  ClientPtr client_ptr;
222	  HIXL_CHK_STATUS_RET(AutoConnect(remote_engine, kAutoConnectTimeout, client_ptr),
223	                      "[HixlEngine] Failed to auto connect before TransferAsync, local_engine:%s, remote_engine:%s",
224	                      local_engine_.c_str(), remote_engine.GetString());
225	  Status trans_status = client_ptr->TransferAsync(op_descs, operation, optional_args, req);
226	  if (trans_status != SUCCESS) {
227	    HIXL_LOGE(trans_status, "[HixlEngine] Failed to TransferAsync, local_engine:%s, remote_engine:%s",
228	              local_engine_.c_str(), remote_engine.GetString());
229	    HIXL_CHK_STATUS_RET(AutoDisconnect(remote_engine, kAutoConnectTimeout),
230	                        "[HixlEngine] Failed to disconnect on error.");
231	    return trans_status;
232	  }
233	  client_manager_.RegisterTransferReq(req, client_ptr, optional_args.user_data);
234	  HIXL_LOGI("[HixlEngine] Asynchronous transmission succeeded, local_engine:%s, remote_engine:%s",
235	            local_engine_.c_str(), remote_engine.GetString());
236	  return SUCCESS;
237	}
238	
239	Status HixlEngine::GetTransferStatus(const TransferReq &req, TransferStatus &status) {
240	  ClientPtr client = client_manager_.GetClientByReq(req);
241	  if (client == nullptr) {
242	    status = TransferStatus::FAILED;
243	  }
244	  HIXL_CHK_BOOL_RET_STATUS(client != nullptr, PARAM_INVALID,
245	                           "[HixlEngine] Request not found, request has been completed or does not exist, req:%p", req);
246	  Status ret = client->GetTransferStatus(req, status);
247	  if (ret != SUCCESS) {
248	    HIXL_LOGE(ret, "[HixlEngine] Failed to get status through client, local_engine:%s, req:%p, status:%d",
249	              local_engine_.c_str(), req, static_cast<int32_t>(status));
250	    client_manager_.EraseTransferReq(req);
251	    HIXL_CHK_STATUS_RET(AutoDisconnect(AscendString(client->GetRemoteEngine().c_str()), kAutoConnectTimeout),
252	                        "[HixlEngine] Failed to disconnect on error.");
253	    return ret;
254	  }
255	  if (status != TransferStatus::WAITING) {
256	    client_manager_.EraseTransferReq(req);
257	  }
258	  return SUCCESS;
259	}
260	
261	Status HixlEngine::GetTransferStatus(const GetTransferStatusArgs &args, std::vector<TransferResult> &results) {
262	  results.clear();
263	  if (args.max_query_count == 0) {
264	    return SUCCESS;
265	  }
266	  auto reqs = client_manager_.GetOrderedReqs(0);
267	  results.reserve(reqs.size());
268	  std::unordered_set<std::string> disconnected_engines;
269	  for (const auto &it : reqs) {
270	    TransferReq req = it.req;
271	    ClientPtr client = it.client;
272	    if (client == nullptr) {
273	      client_manager_.EraseTransferReq(req);
274	      continue;
275	    }
276	    const std::string remote_engine = client->GetRemoteEngine();
277	    if (disconnected_engines.count(remote_engine) != 0U) {
278	      client_manager_.EraseTransferReq(req);
279	      results.emplace_back(TransferResult{req, it.user_data, TransferStatus::FAILED});
280	      if (results.size() >= static_cast<size_t>(args.max_query_count)) {
281	        break;
282	      }
283	      continue;
284	    }
285	    TransferStatus status = TransferStatus::FAILED;
286	    Status ret = client->GetTransferStatus(req, status);
287	    status = (ret == SUCCESS) ? status : TransferStatus::FAILED;
288	    if (ret != SUCCESS) {
289	      HIXL_LOGE(ret, "[HixlEngine] Failed to get status through client, local_engine:%s, req:%p, status:%d",
290	                local_engine_.c_str(), req, static_cast<int32_t>(status));
291	      if (disconnected_engines.insert(remote_engine).second) {
292	        (void)AutoDisconnect(AscendString(remote_engine.c_str()), kAutoConnectTimeout);
293	      }
294	    }
295	    if (status != TransferStatus::WAITING) {
296	      client_manager_.EraseTransferReq(req);
297	    }
298	    if (args.skip_waiting && status == TransferStatus::WAITING) {
299	      continue;
300	    }
301	    results.emplace_back(TransferResult{req, it.user_data, status});
302	    if (results.size() >= static_cast<size_t>(args.max_query_count)) {
303	      break;
304	    }
305	  }
306	  return SUCCESS;
307	}
308	
309	void HixlEngine::Finalize() {
310	  HIXL_EVENT("[HixlEngine] finalize start, local_engine:%s", local_engine_.c_str());
311	  std::lock_guard<std::mutex> lock(mutex_);
312	  is_initialized_ = false;
313	  {
314	    auto with_context = aclrt_context_.GetContextGuard();
315	    server_.Finalize();
316	    client_manager_.Finalize();
317	    mem_map_.clear();
318	  }
319	  aclrt_context_.DestroyContext();
320	  HIXL_EVENT("[HixlEngine] finalize success, local_engine:%s", local_engine_.c_str());
321	}
322	
323	Status HixlEngine::SendNotify(const AscendString &remote_engine, const NotifyDesc &notify, int32_t timeout_in_millis) {
324	  HIXL_LOGI("[HixlEngine] SendNotify started, local_engine:%s, remote_engine:%s, timeout:%d ms", local_engine_.c_str(),
325	            remote_engine.GetString(), timeout_in_millis);
326	  auto with_context = aclrt_context_.GetContextGuard();
327	  ClientPtr client_ptr = client_manager_.GetClient(remote_engine.GetString());
328	  HIXL_CHK_BOOL_RET_STATUS(client_ptr != nullptr, NOT_CONNECTED,
329	                           "[HixlEngine] Failed to get client, remote_engine:%s is not connected",
330	                           remote_engine.GetString());
331	
332	  HIXL_CHK_STATUS_RET(client_ptr->SendNotify(notify, timeout_in_millis),
333	                      "[HixlEngine] Failed to SendNotify, local_engine:%s, remote_engine:%s", local_engine_.c_str(),
334	                      remote_engine.GetString());
335	  HIXL_LOGI("[HixlEngine] SendNotify succeeded, local_engine:%s, remote_engine:%s", local_engine_.c_str(),
336	            remote_engine.GetString());
337	  return SUCCESS;
338	}
339	
340	Status HixlEngine::GetNotifies(std::vector<NotifyDesc> &notifies) {
341	  HIXL_LOGI("[HixlEngine] GetNotifies started, local_engine:%s", local_engine_.c_str());
342	  auto with_context = aclrt_context_.GetContextGuard();
343	  HIXL_CHK_STATUS_RET(server_.GetNotifies(notifies), "[HixlEngine] Failed to get notifies from server, local_engine:%s",
344	                      local_engine_.c_str());
345	  HIXL_LOGI("[HixlEngine] GetNotifies succeeded, local_engine:%s, count:%zu", local_engine_.c_str(), notifies.size());
346	  return SUCCESS;
347	}
348	
349	Status HixlEngine::RegisterCallbackProcessor(int32_t msg_type, CallbackProcessor processor) {
350	  auto with_context = aclrt_context_.GetContextGuard();
351	  HIXL_CHK_STATUS_RET(server_.RegisterCallbackProcessor(msg_type, processor),
352	                      "[HixlEngine] Failed to register msg callback, msg type:%d", msg_type);
353	  return SUCCESS;
354	}
355	
356	Status HixlEngine::CheckInitialized() const {
357	  HIXL_CHK_BOOL_RET_STATUS(is_initialized_.load(std::memory_order_acquire), FAILED,
358	                           "[HixlEngine] engine is not initialized, local_engine:%s", local_engine_.c_str());
359	  return SUCCESS;
360	}
361	
362	void HixlEngine::FillClientConfigFields(const AscendString &remote_engine, ClientConfig &config,
363	                                        int32_t timeout_in_millis, bool is_lazy) const {
364	  config.endpoint_list = endpoint_list_;
365	  config.local_engine = local_engine_;
366	  config.remote_engine = remote_engine.GetString();
367	  config.rdma_tc = rdma_traffic_class_;
368	  config.rdma_sl = rdma_service_level_;
369	  config.timeout_ms = static_cast<uint32_t>(timeout_in_millis);
370	  config.qos = qos_;
371	  config.max_active_channels = max_active_channels_;
372	  config.is_lazy = is_lazy;
373	}
374	
375	void HixlEngine::CopyMemInfoListLocked(std::vector<MemHandleInfo> &mem_info_list) const {
376	  for (const auto &pair : mem_map_) {
377	    mem_info_list.push_back(pair.second);
378	  }
379	}
380	
381	Status HixlEngine::AutoConnect(const AscendString &remote_engine, int32_t timeout_in_millis, ClientPtr &client_ptr) {
382	  HIXL_CHK_STATUS_RET(CheckInitialized(), "[HixlEngine] Failed to auto connect, engine is not initialized");
383	  if (!auto_connect_) {
384	    client_ptr = client_manager_.GetClient(remote_engine.GetString());
385	    HIXL_CHK_BOOL_RET_STATUS(client_ptr != nullptr, NOT_CONNECTED,
386	                             "[HixlEngine] Failed to get client through remote engine, please check connection. "
387	                             "local_engine:%s, remote_engine:%s",
388	                             local_engine_.c_str(), remote_engine.GetString());
389	    return SUCCESS;
390	  }
391	  HIXL_CHK_BOOL_RET_STATUS(strcmp(local_engine_.c_str(), remote_engine.GetString()) != 0, PARAM_INVALID,
392	                           "[HixlEngine] Do not support connection with self, please check remote engine. "
393	                           "local_engine:%s, remote_engine:%s",
394	                           local_engine_.c_str(), remote_engine.GetString());
395	  client_ptr = client_manager_.GetClient(remote_engine.GetString());
396	  if (client_ptr != nullptr) {
397	    return SUCCESS;
398	  }
399	  ClientConfig config{};
400	  std::vector<MemHandleInfo> mem_info_list;
401	  BuildClientConfig(remote_engine, config, mem_info_list, timeout_in_millis);
402	  HIXL_LOGI("[HixlEngine] Auto connect started, local_engine:%s, remote_engine:%s, timeout:%d ms.",
403	            local_engine_.c_str(), remote_engine.GetString(), timeout_in_millis);
404	  Status ret = client_manager_.GetOrCreateClient(config, mem_info_list, timeout_in_millis, client_ptr);
405	  if (ret == ALREADY_CONNECTED) {
406	    return SUCCESS;
407	  }
408	  HIXL_CHK_STATUS_RET(ret, "[HixlEngine] Failed to auto connect, local_engine:%s, remote_engine:%s, timeout:%d ms",
409	                      local_engine_.c_str(), remote_engine.GetString(), timeout_in_millis);
410	  return SUCCESS;
411	}
412	
413	void HixlEngine::BuildClientConfig(const AscendString &remote_engine, ClientConfig &config,
414	                                   std::vector<MemHandleInfo> &mem_info_list, int32_t timeout_in_millis) const {
415	  FillClientConfigFields(remote_engine, config, timeout_in_millis, auto_connect_);
416	  std::lock_guard<std::mutex> lock(mutex_);
417	  CopyMemInfoListLocked(mem_info_list);
418	}
419	
420	Status HixlEngine::AutoDisconnect(const AscendString &remote_engine, int32_t timeout_in_millis) {
421	  if (auto_connect_) {
422	    if (client_manager_.GetClient(remote_engine.GetString()) == nullptr) {
423	      return SUCCESS;
424	    }
425	    HIXL_CHK_STATUS_RET(Disconnect(remote_engine, timeout_in_millis),
426	                        "[HixlEngine] Failed to disconnect on error, remote_engine:%s, timeout:%d ms",
427	                        remote_engine.GetString(), timeout_in_millis);
428	  }
429	  return SUCCESS;
430	}
431	}  // namespace hixl
