53	Status HixlClient::Initialize(const std::vector<EndpointConfig> &local_endpoint_list, uint32_t timeout_ms,
54	                              bool is_lazy) {
55	  std::lock_guard<std::mutex> lock(mutex_);
56	  HIXL_CHK_BOOL_RET_STATUS(!local_endpoint_list.empty(), PARAM_INVALID, "The input local_endpoint_list is empty");
57	  std::vector<EndpointConfig> remote_endpoint_list;
58	  CtrlMsgPlugin::Initialize();
59	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Connect(server_ip_, server_port_, ctrl_socket_, timeout_ms),
60	                      "Connect socket failed");
61	  HIXL_DISMISSABLE_GUARD(close_ctrl_socket, [this] { CloseCtrlSocket(); });
62	  HIXL_CHK_STATUS_RET(SendEndpointInfoReq(ctrl_socket_, CtrlMsgType::kGetEndpointInfoReq),
63	                      "HixlClient send GetEndpointInfoReq failed, socket:%d", ctrl_socket_);
64	  HIXL_CHK_STATUS_RET(RecvEndpointInfoResp(ctrl_socket_, remote_endpoint_list, timeout_ms),
65	                      "HixlClient receive GetEndpointInfoResp failed, socket:%d", ctrl_socket_);
66	  HIXL_CHK_BOOL_RET_STATUS(!remote_endpoint_list.empty(), FAILED, "HixlClient received empty remote_endpoint_list");
67	  std::vector<HandlerCreateArgs::EndpointPair> matched_pairs;
68	  HandlerCreateArgs::HandlerType handler_type;
69	  HIXL_CHK_STATUS_RET(
70	      EndpointMatcher::MatchEndpoints(local_endpoint_list, remote_endpoint_list, matched_pairs, handler_type),
71	      "EndpointMatcher::MatchEndpoints failed");
72	  link_pairs_ = matched_pairs;
73	  HIXL_EVENT("[HixlClient] link selected, local_engine:%s, remote_engine:%s, handler:%s, pair_count:%zu",
74	             local_engine_.c_str(), remote_engine_.c_str(), EndpointMatcher::HandlerTypeToString(handler_type),
75	             matched_pairs.size());
76	  for (size_t i = 0; i < matched_pairs.size(); ++i) {
77	    const auto &pair = matched_pairs[i];
78	    HIXL_EVENT(
79	        "[HixlClient] link pair[%zu], local_engine:%s, remote_engine:%s, comm_type:%s, "
80	        "local_endpoint:{%s}, remote_endpoint:{%s}",
81	        i, local_engine_.c_str(), remote_engine_.c_str(), CommTypeToString(pair.type), pair.local.ToString().c_str(),
82	        pair.remote.ToString().c_str());
83	  }
84	  HandlerCreateArgs args{
85	      server_ip_,    server_port_,         rdma_tc_, rdma_sl_,   handler_type, std::move(matched_pairs),
86	      qos_,          max_active_channels_, is_lazy,  timeout_ms, ctrl_socket_, local_engine_,
87	      remote_engine_};
88	  client_handler_ = ClientHandlerFactory::Create(args);
89	  HIXL_CHECK_NOTNULL(client_handler_, "ClientHandlerFactory create handler failed");
90	  HIXL_DISMISS_GUARD(close_ctrl_socket);
