94	Status HixlClient::SendEndpointInfoReq(int32_t fd, CtrlMsgType msg_type) const {
95	  CtrlMsgHeader header{};
96	  header.magic = kMagicNumber;
97	  header.body_size = static_cast<uint64_t>(sizeof(CtrlMsgType));
98	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &header, static_cast<uint64_t>(sizeof(header))),
99	                      "HixlClient send header failed, fd:%d", fd);
100	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &msg_type, static_cast<uint64_t>(sizeof(msg_type))),
101	                      "HixlClient send msg_type failed, fd:%d", fd);
102	  return SUCCESS;
