208	int32_t Transfer(EngineCtx &ctx_a, EngineCtx &ctx_b) {
209	  std::vector<TransferOpDesc> descs;
210	  descs.reserve(kXferBlockCount);
211	  for (size_t i = 0; i < kXferBlockCount; ++i) {
212	    TransferOpDesc desc{};
213	    desc.local_addr = reinterpret_cast<uintptr_t>(ctx_a.dev_buf) + i * kXferBlockSize;
214	    desc.remote_addr = reinterpret_cast<uintptr_t>(ctx_b.dev_buf) + i * kXferBlockSize;
215	    desc.len = kXferBlockSize;
216	    descs.push_back(desc);
217	  }
218	  auto ret = ctx_a.engine.TransferSync(ctx_b.name, WRITE, descs, kXferTimeout);
219	  if (ret != SUCCESS) {
220	    printf("[ERROR] TransferSync %s->%s failed, ret=%u, errmsg:%s\n", ctx_a.name, ctx_b.name, ret, GetRecentErrMsg());
221	    return -1;
222	  }
223	  printf("[INFO] Transfer completed\n");
224	  return 0;
225	}
